<script setup lang="ts">
import {t as tr} from "../i18n";
import {ref,watch,onUnmounted} from 'vue';import {useEvidenceUpload} from '../stores/evidence-upload';import {useBusinessStore} from '../stores/business';
const props=defineProps<{targetKind:string;targetId:string}>(),emit=defineEmits<{saved:[]}>(),upload=useEvidenceUpload(),business=useBusinessStore(),processing=ref(false),preview=ref('');
function revoke(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';}
async function select(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;processing.value=true;upload.error='';try{let result=file;
 if(file.type.startsWith('image/')&&file.size>3*1024*1024){const bitmap=await createImageBitmap(file),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(!blob)throw new Error('图片压缩未完成，请选择较小的照片');result=new File([blob],file.name.replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'});}
 if(result.size>3*1024*1024)throw new Error('附件最大 3 MiB，请选择较小的文件');revoke();upload.select(result);if(result.type.startsWith('image/'))preview.value=URL.createObjectURL(result);
 }catch(e){upload.error=(e as Error).message;}finally{processing.value=false;(event.target as HTMLInputElement).value='';}}
async function send(){const result=await upload.upload(business.scopeKey,props.targetKind,props.targetId);if(result){revoke();emit('saved');}}
watch(()=>[props.targetKind,props.targetId,business.scopeKey],()=>{upload.clearPrivate();revoke();});onUnmounted(()=>{upload.cancel();revoke();});
</script>
<template><div class="evidence-upload"><label>{{tr("拍照作为人工证据")}}<input :aria-label="tr('拍照上传')" type="file" accept="image/png,image/jpeg,image/webp" capture="environment" :disabled="upload.busy||processing" @change="select"></label><label>{{tr("相册或文件")}}<input :aria-label="tr('选择证据文件')" type="file" accept="image/png,image/jpeg,image/webp,application/pdf,text/plain" :disabled="upload.busy||processing" @change="select"></label><p v-if="processing" role="status">{{tr("正在处理照片…")}}</p><template v-if="upload.file"><img v-if="preview" :src="preview" alt="待上传的人工证据预览"><p>{{upload.file.name}} · {{Math.ceil(upload.file.size/1024)}} {{tr("KiB · 绑定")}} {{targetId}}</p><p class="mobile-source">{{tr("请求")}} {{upload.requestId}} {{tr("· 重试沿用此编号")}}</p><div class="button-row"><button :disabled="upload.busy||processing" @click="send">{{tr(upload.error?'重试同一上传':'上传人工证据（≤3 MiB）')}}</button><button :disabled="upload.busy" @click="upload.clearPrivate();revoke()">{{tr("删除待上传草稿")}}</button></div></template><p v-if="upload.busy" role="status">{{tr("上传")}} {{upload.progress}}{{tr("% · 等待主系统保存确认")}}</p><progress v-if="upload.busy" :value="upload.progress" max="100" :aria-label="tr('证据上传进度')"/><p v-if="upload.error" role="alert">{{upload.error}}</p><p v-if="upload.receipt">{{tr("已保存证据")}} {{upload.receipt.id}} · SHA256 {{upload.receipt.sha256}}</p></div></template>
<style scoped>.evidence-upload{display:grid;gap:12px;margin:16px 0}.evidence-upload label{display:grid;gap:8px}.evidence-upload img{max-width:100%;max-height:220px;object-fit:contain}.evidence-upload progress{width:100%}</style>
